window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e8641bcbd3eec7a2"]={"versions": [{"id": "FIG-e8641bcbd3eec7a2", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm (AUTOSAR Adaptive Platform, Manifest Specification).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die formale Bindung auf Deployment-Ebene zwischen zwei Functional Clustern (FC) der Adaptive Platform: <em>Update and Configuration Management</em> (UCM) und <em>Time Synchronization</em> (Time Sync).</li>\n<li><strong>Zweck:</strong> Ermöglicht die explizite Zuweisung einer synchronisierten oder lokalen Zeitbasis (<code>TimeBaseResource</code>) an eine spezifische UCM-Instanz (<code>UcmModuleInstantiation</code>) innerhalb des Machine- bzw. Platform-Manifests (TPS_MANI_01374, TPS_MANI_01379, RS_MANI_00023).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>UcmToTimeBaseResourceMapping</code>:</strong></li>\n<li>Konkrete Assoziationsklasse für das Inter-Cluster-Mapping.</li>\n<li>Generalisiert/erbt von den abstrakten Metaklassen <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> und <code>UploadableDeploymentElement</code>.</li>\n<li><strong><code>TimeBaseResource</code>:</strong></li>\n<li>Spezialisiert die abstrakte Metaklasse <code>Identifiable</code> (stellt <code>shortName</code>, <code>category</code>, UUID bereit).</li>\n<li>Repräsentiert eine deklarierte Zeitbasis-Ressource des <em>Time Synchronization Functional Clusters</em> (z. B. synchronisierte globale Zeitdomäne oder freilaufender Monotonic Clock).</li>\n<li><strong><code>UcmModuleInstantiation</code>:</strong></li>\n<li>Spezialisiert <code>NonOsModuleInstantiation</code> (Instanziierung eines AUTOSAR Adaptive Core-/Plattform-Moduls außerhalb von Standard-OS-Prozessen).</li>\n<li>Repräsentiert die deployte UCM-Modulinstanz auf einer Adaptive Machine.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ identifier: String [0..1]</code>: Eindeutiger logischer Bezeichner der UCM-Instanz.</li>\n<li><code>+ maxBlockSize: PositiveInteger [0..1]</code>: Maximale Blockgröße in Bytes für Datentransfer- und Streaming-Operationen bei Software-Paketübertragungen.</li>\n<li><code>+ version: StrongRevisionLabelString [0..1]</code>: Eindeutiges Versions- und Revisionslabel der UCM-Implementierung.</li>\n<li><strong>Assoziationen & Kardinalitäten:</strong></li>\n<li><code>+timeBaseResource</code> (<code>UcmToTimeBaseResourceMapping</code> $\\rightarrow$ <code>TimeBaseResource</code>): Unidirektionale Referenz mit Multiplizität <code>0..1</code>.</li>\n<li><code>+ucm</code> (<code>UcmToTimeBaseResourceMapping</code> $\\rightarrow$ <code>UcmModuleInstantiation</code>): Unidirektionale Referenz mit Multiplizität <code>0..1</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (Konfigurations- &amp; Laufzeitkontext)</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Metamodell:</strong> Kein dynamisches Ablaufdiagramm; definiert den Konfigurationsrahmen für die Plattform-Initialisierung.</li>\n<li><strong>Laufzeit-Bezug:</strong></li>\n<li><strong>Initialisierung:</strong> Zur Boot-Phase initialisiert die Adaptive Platform den UCM-Dämon/Prozess und bindet diesen über die interne Time-Sync-Schnittstelle (<code>ara::ts</code>) an die im Mapping spezifizierte <code>TimeBaseResource</code>.</li>\n<li><strong>Nutzung im UCM-Lifecycle:</strong> Der UCM nutzt diese Zeitbasis für deterministisches Timestamping von Installations-/Rollback-Historien, Validierung von Zertifikatsgültigkeiten (Not-Before/Not-After) bei Software-Paketsignaturen sowie Protokollierung von Kampagnen-Zustandsübergängen.</li>\n<li><strong>Fallback-Verhalten:</strong> Bei fehlendem Mapping (<code>0..1</code>) arbeitet UCM ohne externe Zeitbasis-Bindung, was den Funktionsumfang bei zeitkritischen Gültigkeitsprüfungen einschränkt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Autoren & Systemintegratoren:</strong></li>\n<li>Das ARXML-Element <code>UcmToTimeBaseResourceMapping</code> muss definiert werden, wenn UCM-Events gegen eine fahrzeugweite Master-Clock (z. B. IEEE 802.1AS / gPTP) synchronisiert werden müssen.</li>\n<li>Da beide Referenzen optional (<code>0..1</code>) modelliert sind, müssen Generatoren und Validatoren absichern, dass eine unvollständige Instanziierung (Mapping ohne Ziel) zur Build-Zeit erkannt und gemeldet wird.</li>\n<li><strong>Stack- & Plattform-Entwickler:</strong></li>\n<li>Die Konfiguration von <code>maxBlockSize</code> determiniert direkt die Pufferallokation der internen Transfer-APIs (<code>ara::ucm</code>) und begrenzt die maximale Chunk-Größe beim Block-Transfer von Software-Paketen.</li>\n<li>Das UCM-Modul darf keinen hardkodierten Zugriff auf eine Standard-Zeitbasis annehmen; die Bindung an den TimeSync-Provider erfolgt ausschließlich über die durch dieses Mapping generierte Konfigurationsinstanz.</li>\n</ul>"}, {"id": "FIG-9518372b7ea66693", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm (AUTOSAR Adaptive Platform, Manifest Specification).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die formale Bindung auf Deployment-Ebene zwischen zwei Functional Clustern (FC) der Adaptive Platform: <em>Update and Configuration Management</em> (UCM) und <em>Time Synchronization</em> (Time Sync).</li>\n<li><strong>Zweck:</strong> Ermöglicht die explizite Zuweisung einer synchronisierten oder lokalen Zeitbasis (<code>TimeBaseResource</code>) an eine spezifische UCM-Instanz (<code>UcmModuleInstantiation</code>) innerhalb des Machine- bzw. Platform-Manifests (TPS_MANI_01374, TPS_MANI_01379, RS_MANI_00023).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>UcmToTimeBaseResourceMapping</code>:</strong></li>\n<li>Konkrete Assoziationsklasse für das Inter-Cluster-Mapping.</li>\n<li>Generalisiert/erbt von den abstrakten Metaklassen <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> und <code>UploadableDeploymentElement</code>.</li>\n<li><strong><code>TimeBaseResource</code>:</strong></li>\n<li>Spezialisiert die abstrakte Metaklasse <code>Identifiable</code> (stellt <code>shortName</code>, <code>category</code>, UUID bereit).</li>\n<li>Repräsentiert eine deklarierte Zeitbasis-Ressource des <em>Time Synchronization Functional Clusters</em> (z. B. synchronisierte globale Zeitdomäne oder freilaufender Monotonic Clock).</li>\n<li><strong><code>UcmModuleInstantiation</code>:</strong></li>\n<li>Spezialisiert <code>NonOsModuleInstantiation</code> (Instanziierung eines AUTOSAR Adaptive Core-/Plattform-Moduls außerhalb von Standard-OS-Prozessen).</li>\n<li>Repräsentiert die deployte UCM-Modulinstanz auf einer Adaptive Machine.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ identifier: String [0..1]</code>: Eindeutiger logischer Bezeichner der UCM-Instanz.</li>\n<li><code>+ maxBlockSize: PositiveInteger [0..1]</code>: Maximale Blockgröße in Bytes für Datentransfer- und Streaming-Operationen bei Software-Paketübertragungen.</li>\n<li><code>+ version: StrongRevisionLabelString [0..1]</code>: Eindeutiges Versions- und Revisionslabel der UCM-Implementierung.</li>\n<li><strong>Assoziationen & Kardinalitäten:</strong></li>\n<li><code>+timeBaseResource</code> (<code>UcmToTimeBaseResourceMapping</code> $\\rightarrow$ <code>TimeBaseResource</code>): Unidirektionale Referenz mit Multiplizität <code>0..1</code>.</li>\n<li><code>+ucm</code> (<code>UcmToTimeBaseResourceMapping</code> $\\rightarrow$ <code>UcmModuleInstantiation</code>): Unidirektionale Referenz mit Multiplizität <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Metamodell:</strong> Kein dynamisches Ablaufdiagramm; definiert den Konfigurationsrahmen für die Plattform-Initialisierung.</li>\n<li><strong>Laufzeit-Bezug:</strong></li>\n<li><strong>Initialisierung:</strong> Zur Boot-Phase initialisiert die Adaptive Platform den UCM-Dämon/Prozess und bindet diesen über die interne Time-Sync-Schnittstelle (<code>ara::ts</code>) an die im Mapping spezifizierte <code>TimeBaseResource</code>.</li>\n<li><strong>Nutzung im UCM-Lifecycle:</strong> Der UCM nutzt diese Zeitbasis für deterministisches Timestamping von Installations-/Rollback-Historien, Validierung von Zertifikatsgültigkeiten (Not-Before/Not-After) bei Software-Paketsignaturen sowie Protokollierung von Kampagnen-Zustandsübergängen.</li>\n<li><strong>Fallback-Verhalten:</strong> Bei fehlendem Mapping (<code>0..1</code>) arbeitet UCM ohne externe Zeitbasis-Bindung, was den Funktionsumfang bei zeitkritischen Gültigkeitsprüfungen einschränkt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Autoren & Systemintegratoren:</strong></li>\n<li>Das ARXML-Element <code>UcmToTimeBaseResourceMapping</code> muss definiert werden, wenn UCM-Events gegen eine fahrzeugweite Master-Clock (z. B. IEEE 802.1AS / gPTP) synchronisiert werden müssen.</li>\n<li>Da beide Referenzen optional (<code>0..1</code>) modelliert sind, müssen Generatoren und Validatoren absichern, dass eine unvollständige Instanziierung (Mapping ohne Ziel) zur Build-Zeit erkannt und gemeldet wird.</li>\n<li><strong>Stack- & Plattform-Entwickler:</strong></li>\n<li>Die Konfiguration von <code>maxBlockSize</code> determiniert direkt die Pufferallokation der internen Transfer-APIs (<code>ara::ucm</code>) und begrenzt die maximale Chunk-Größe beim Block-Transfer von Software-Paketen.</li>\n<li>Das UCM-Modul darf keinen hardkodierten Zugriff auf eine Standard-Zeitbasis annehmen; die Bindung an den TimeSync-Provider erfolgt ausschließlich über die durch dieses Mapping generierte Konfigurationsinstanz.</li>\n</ul>"}], "trans": [{"from": "FIG-e8641bcbd3eec7a2", "to": "FIG-9518372b7ea66693", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
